import ast
import os
import sys
import subprocess
import tempfile
import shutil
import time
import json
import re
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple, Iterable

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Dependency on artifacts.py (assumed to be available in the same package or importable)
try:
    from hae.evaluation.artifacts import (
        is_generated_path,
        is_malformed_path,
        sanitize_path,
        filter_bundle,
        partition_bundle,
        count_source_files
    )
except ImportError:
    # Fallback implementations if artifacts.py is not yet available or importable
    # These match the specification provided in the prompt for artifacts.py
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path != path.strip():
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        path = path.strip()
        path = path.replace('*', '').replace('`', '')
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in bundle:
            if any(path.endswith(s) for s in suffixes):
                count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files}, Python Files: {self.python_files}")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append(f"Pass Rate: {self.pass_rate:.2%}")
        lines.append("Gates:")
        for g in self.gates:
            lines.append(f"  [{g.status.upper():7}] {g.name:10} ({g.method}): {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional filename hint
    # Pattern: ```[language] [filename]\n...\n```
    # We look for lines starting with ```
    blocks = {}
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i]
        if line.strip().startswith('```'):
            # Extract potential filename from the fence line
            # e.g., ```python src/main.py
            fence_content = line.strip()[3:].strip()
            parts = fence_content.split()
            filename = None
            if parts:
                # Heuristic: if the first part looks like a path, use it
                # Otherwise, if there's a second part, use that
                if len(parts) > 1:
                    filename = parts[1]
                elif len(parts) == 1 and ('/' in parts[0] or '.' in parts[0]):
                    filename = parts[0]

            # Collect content until closing ```
            content_lines = []
            i += 1
            while i < len(lines):
                if lines[i].strip().startswith('```'):
                    break
                content_lines.append(lines[i])
                i += 1

            if filename:
                # Sanitize filename if needed
                clean_filename = sanitize_path(filename)
                if clean_filename:
                    blocks[clean_filename] = "\n".join(content_lines)
        i += 1

    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            if hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace'
            elif hasattr(workspace, 'list_files'):
                # Assume it's a directory-like object or has a method to get files
                # This is a heuristic; typically workspace is a dict or object with .files
                pass

        # If no bundle from workspace, try extracting from deliverable text
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        if not bundle:
            # Empty workspace
            return self._empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def _empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast_parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='packaging', detail='No packaging metadata found'),
            GateResult(name='smoke', status=FAILED, method='import', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest', detail='No test files found'),
            GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No telemetry usage found'),
        ]
        failed_count = sum(1 for g in gates if g.status == FAILED)
        return VerificationReport(
            gates=gates,
            score_penalty=failed_count * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source
        )

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to get authored files
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files_count = len(authored_bundle)
        python_files_count = count_source_files(authored_bundle, suffixes=('.py',))

        # Create temp directory
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to disk
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            # Run verification on the directory
            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory for files
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Filter out generated dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        full_path = os.path.join(root, file)
                        try:
                            with open(full_path, 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        authored_files_count = len(authored)
        python_files_count = count_source_files(authored, suffixes=('.py',))

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files_count,
            python_files=python_files_count,
            source=source
        )

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = 'ast_parse'
        py_files = [p for p in authored if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method=method,
                detail='No Python files found',
                duration_s=time.time() - start_time
            )

        errors = []
        for path in py_files:
            content = authored[path]
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start_time
        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method=method,
                detail='Syntax errors found: ' + '; '.join(errors),
                duration_s=duration
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method=method,
            detail=f'All {len(py_files)} Python files parsed successfully',
            duration_s=duration
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = 'packaging'

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(
                name='build',
                status=FAILED,
                method=method,
                detail='No packaging metadata (pyproject.toml, setup.py, or setup.cfg) found',
                duration_s=time.time() - start_time
            )

        # Validate pyproject.toml if present
        if has_pyproject:
            try:
                import tomllib
            except ImportError:
                try:
                    import tomli as tomllib
                except ImportError:
                    return GateResult(
                        name='build',
                        status=SKIPPED,
                        method=method,
                        detail='tomllib/tomli not available to validate pyproject.toml',
                        duration_s=time.time() - start_time
                    )

            try:
                content = authored['pyproject.toml']
                data = tomllib.loads(content)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(k in data for k in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method=method,
                        detail='pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool])',
                        duration_s=time.time() - start_time
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method=method,
                    detail=f'pyproject.toml is malformed: {e}',
                    duration_s=time.time() - start_time
                )

        # Try to install
        # Check if pip is available
        try:
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], 
                           capture_output=True, timeout=10, check=True)
        except Exception:
            return GateResult(
                name='build',
                status=SKIPPED,
                method=method,
                detail='pip not available or failed to run',
                duration_s=time.time() - start_time
            )

        # Run pip install -e . --no-deps --no-build-isolation
        try:
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            duration = time.time() - start_time
            if result.returncode == 0:
                return GateResult(
                    name='build',
                    status=PASSED,
                    method=method,
                    detail='Package installed successfully',
                    duration_s=duration
                )
            else:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method=method,
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=duration
                )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method=method,
                detail='pip install timed out',
                duration_s=time.time() - start_time
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method=method,
                detail=f'Error running pip install: {e}',
                duration_s=time.time() - start_time
            )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = 'import'

        # Find non-test authored modules
        # Exclude test files
        module_paths = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                continue
            # Convert path to module name
            # e.g., src/foo/bar.py -> foo.bar
            # We need to handle src/ prefix if present
            rel_path = path
            if rel_path.startswith('src/'):
                rel_path = rel_path[4:]

            if rel_path.endswith('.py'):
                module_name = rel_path[:-3].replace('/', '.').replace('\\', '.')
                if module_name:
                    module_paths.append(module_name)

        if not module_paths:
            return GateResult(
                name='smoke',
                status=FAILED,
                method=method,
                detail='No importable non-test modules found',
                duration_s=time.time() - start_time
            )

        # Set up PYTHONPATH
        env = os.environ.copy()
        python_path = env.get('PYTHONPATH', '')
        new_paths = [workdir, os.path.join(workdir, 'src')]
        if python_path:
            env['PYTHONPATH'] = os.pathsep.join(new_paths + [python_path])
        else:
            env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # Try to import each module in a subprocess
        failed_modules = []
        skipped_modules = []

        for module_name in module_paths:
            code = f"import {module_name}"
            try:
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                if result.returncode != 0:
                    stderr = result.stderr
                    # Check for ModuleNotFoundError for third-party packages
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package (not part of the workspace)
                        # This is a heuristic: if the missing module is not in our authored files
                        # We assume it's third-party if it's not a local module
                        # For simplicity, if ModuleNotFoundError is raised, we check if the module name
                        # corresponds to a file we have. If not, it's likely third-party.
                        # However, the spec says: "If module imports fail solely with ModuleNotFoundError for uninstalled third-party packages... return SKIPPED"
                        # If ANY module fails with ModuleNotFoundError, we might skip the whole gate?
                        # "If no importable modules exist or any module fails with a syntax or runtime error, return FAILED."
                        # "If module imports fail solely with ModuleNotFoundError... return SKIPPED"

                        # Let's collect errors. If we see ModuleNotFoundError, we mark as skipped candidate.
                        # If we see other errors, we mark as failed.
                        skipped_modules.append(module_name)
                    else:
                        failed_modules.append(f"{module_name}: {stderr}")
            except Exception as e:
                failed_modules.append(f"{module_name}: {e}")

        duration = time.time() - start_time

        if failed_modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method=method,
                detail='Import errors: ' + '; '.join(failed_modules),
                duration_s=duration
            )

        if skipped_modules:
            return GateResult(
                name='smoke',
                status=SKIPPED,
                method=method,
                detail=f'ModuleNotFoundError for third-party packages in: {", ".join(skipped_modules)}',
                duration_s=duration
            )

        return GateResult(
            name='smoke',
            status=PASSED,
            method=method,
            detail=f'All {len(module_paths)} modules imported successfully',
            duration_s=duration
        )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = 'pytest'

        # Find test files
        test_files = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                test_files.append(path)

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method=method,
                detail='No test files found',
                duration_s=time.time() - start_time
            )

        # Set up PYTHONPATH
        env = os.environ.copy()
        python_path = env.get('PYTHONPATH', '')
        new_paths = [workdir, os.path.join(workdir, 'src')]
        if python_path:
            env['PYTHONPATH'] = os.pathsep.join(new_paths + [python_path])
        else:
            env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # Check if pytest is installed
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], 
                           capture_output=True, timeout=10, check=True)
            has_pytest = True
        except Exception:
            has_pytest = False

        if has_pytest:
            # Run pytest
            try:
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest', '-v', '--tb=short'],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                duration = time.time() - start_time
                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='pytest',
                        detail='All tests passed',
                        duration_s=duration
                    )
                else:
                    # Check if failure is due to ModuleNotFoundError
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                        return GateResult(
                            name='tests',
                            status=SKIPPED,
                            method='pytest',
                            detail='Tests skipped due to ModuleNotFoundError',
                            duration_s=duration
                        )
                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='pytest',
                        detail=f'Tests failed: {result.stdout[-500:]}',
                        duration_s=duration
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail='Tests timed out',
                    duration_s=time.time() - start_time
                )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail=f'Error running pytest: {e}',
                    duration_s=time.time() - start_time
                )
        else:
            # Stdlib fallback
            method = 'unittest_fallback'
            # Run a script that imports each test file and collects/executes tests
            # We need to handle both bare test_* functions and unittest.TestCase

            script = """
import sys
import os
import unittest
import importlib
import traceback

test_files = sys.argv[1:]
collected_tests = 0
failed_tests = 0
skipped_tests = 0
errors = []

for test_file in test_files:
    try:
        # Convert path to module name
        # Remove .py
        module_name = test_file.replace('.py', '').replace('/', '.').replace('\\\\', '.')
        # Try to import
        mod = importlib.import_module(module_name)

        # Collect bare test_* functions
        for attr_name in dir(mod):
            if attr_name.startswith('test_'):
                attr = getattr(mod, attr_name)
                if callable(attr) and not isinstance(attr, type):
                    # Check if it takes 0 required args
                    import inspect
                    sig = inspect.signature(attr)
                    params = [p for p in sig.parameters.values() if p.default is inspect.Parameter.empty and p.kind in (inspect.Parameter.POSITIONAL_ONLY, inspect.Parameter.POSITIONAL_OR_KEYWORD)]
                    if len(params) == 0:
                        collected_tests += 1
                        try:
                            attr()
                        except Exception as e:
                            failed_tests += 1
                            errors.append(f"{test_file}::{attr_name}: {e}")

        # Collect unittest.TestCase subclasses
        for attr_name in dir(mod):
            attr = getattr(mod, attr_name)
            if isinstance(attr, type) and issubclass(attr, unittest.TestCase) and attr is not unittest.TestCase:
                # Run tests in this class
                suite = unittest.TestLoader().loadTestsFromTestCase(attr)
                runner = unittest.TextTestRunner(verbosity=0)
                result = runner.run(suite)
                collected_tests += result.testsRun
                failed_tests += len(result.failures) + len(result.errors)
                for test, tb in result.failures + result.errors:
                    errors.append(f"{test_file}::{test.id()}: {tb}")
