                        # "If no importable modules exist or any module fails with a syntax or runtime error, return FAILED."
                        # "If module imports fail solely with ModuleNotFoundError... return SKIPPED"

                        # Let's collect errors. If we see ModuleNotFoundError, we mark as skipped candidate.
                        # If we see other errors, we mark as failed.
                        skipped_modules.append(module_name)
                    else:
                        failed_modules.append(f"{module_name}: {stderr}")
            except Exception as e:
                failed_modules.append(f"{module_name}: {e}")

        duration = time.time() - start_time

        if failed_modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method=method,
                detail='Import errors: ' + '; '.join(failed_modules),
                duration_s=duration
            )

        if skipped_modules:
            return GateResult(
                name='smoke',
                status=SKIPPED,
                method=method,
                detail=f'ModuleNotFoundError for third-party packages in: {", ".join(skipped_modules)}',
                duration_s=duration
            )

        return GateResult(
            name='smoke',
            status=PASSED,
            method=method,
            detail=f'All {len(module_paths)} modules imported successfully',
            duration_s=duration
        )

