        # If a test file fails to import due to ModuleNotFoundError, we might skip
        # But the spec says: "If 0 tests are collected because of ModuleNotFoundError... return SKIPPED"
        # If some tests are collected, we continue.
        errors.append(f"{test_file}: ModuleNotFoundError: {e}")
    except Exception as e:
        errors.append(f"{test_file}: {e}")

