def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional filename hint
    # Pattern: ```[language] [filename]\n...\n```
    # We look for lines starting with ```
    blocks = {}
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i]
        if line.strip().startswith('```'):
            # Extract potential filename from the fence line
            # e.g., ```python src/main.py
            fence_content = line.strip()[3:].strip()
            parts = fence_content.split()
            filename = None
            if parts:
                # Heuristic: if the first part looks like a path, use it
                # Otherwise, if there's a second part, use that
                if len(parts) > 1:
                    filename = parts[1]
                elif len(parts) == 1 and ('/' in parts[0] or '.' in parts[0]):
                    filename = parts[0]

            # Collect content until closing ```
            content_lines = []
            i += 1
            while i < len(lines):
                if lines[i].strip().startswith('```'):
                    break
                content_lines.append(lines[i])
                i += 1

            if filename:
                # Sanitize filename if needed
                clean_filename = sanitize_path(filename)
                if clean_filename:
                    blocks[clean_filename] = "\n".join(content_lines)
        i += 1

    return blocks


