            for t in traits_b:
                if t not in seen:
                    combined_traits.append(t)
                    seen.add(t)

            child.ceo.backstory_traits = combined_traits[:6]

            # Average temperature
            avg_temp = (parent_a.ceo.temperature + parent_b.ceo.temperature) / 2.0
            child.ceo.temperature = round(avg_temp, 2)

            # Other CEO attributes: Keep parent_a's for now, or mix?
            # Spec only specifies traits and temperature.
            # We'll keep parent_a's role/goal/backstory as base, maybe mix backstory?
            # Let's just keep parent_a's CEO structure mostly, as it's the base copy.

        # 5. Department Alignment & Crossover

        # Classify departments in both parents
        depts_a = {classify_department_role(d): d for d in parent_a.departments}
        depts_b = {classify_department_role(d): d for d in parent_b.departments}

        # Get all unique categories present in either parent
        all_categories = set(depts_a.keys()) | set(depts_b.keys())

        new_departments = []

        for category in all_categories:
            dept_a = depts_a.get(category)
            dept_b = depts_b.get(category)

            if dept_a and dept_b:
                # Both parents have this category. Perform crossover.
                # Create a new department based on dept_a (or mix)
                # We need to deep copy to avoid mutating parents
                new_dept = dept_a.copy()

                # Crossover Manager
                if dept_a.manager and dept_b.manager:
                    new_dept.manager = dept_a.manager.copy()

                    # Mix manager traits
                    traits_a = dept_a.manager.backstory_traits
                    traits_b = dept_b.manager.backstory_traits
                    combined_traits = []
                    seen = set()
                    for t in traits_a:
                        if t not in seen:
                            combined_traits.append(t)
                            seen.add(t)
                    for t in traits_b:
                        if t not in seen:
                            combined_traits.append(t)
                            seen.add(t)
                    new_dept.manager.backstory_traits = combined_traits[:6]

                    # Mix manager temperature
                    avg_temp = (dept_a.manager.temperature + dept_b.manager.temperature) / 2.0
                    new_dept.manager.temperature = round(avg_temp, 2)

                # Interleave Specialist Agents
                # Take agents from both, interleave them, cap at reasonable number (e.g., 4)
                agents_a = dept_a.agents
                agents_b = dept_b.agents

                interleaved_agents = []
                max_len = max(len(agents_a), len(agents_b))
                for i in range(max_len):
                    if i < len(agents_a):
                        interleaved_agents.append(agents_a[i].copy())
                    if i < len(agents_b):
                        interleaved_agents.append(agents_b[i].copy())

                # Cap at 4 agents to prevent bloat
                new_dept.agents = interleaved_agents[:4]

                # Ensure tools_enabled is preserved or set correctly for technical depts
                if category in TECHNICAL_CATEGORIES:
                    for agent in new_dept.agents:
                        agent.tools_enabled = True
                    if new_dept.manager and new_dept.manager.model_tier == "worker":
                        new_dept.manager.tools_enabled = True

                new_departments.append(new_dept)

            elif dept_a:
                # Only parent A has this category. Inherit from A.
                new_dept = dept_a.copy()
                new_departments.append(new_dept)

            elif dept_b:
                # Only parent B has this category. Inherit from B.
                new_dept = dept_b.copy()
                new_departments.append(new_dept)

        child.departments = new_departments

        # Ensure minimum departments constraint (inherited from Morphogenesis logic usually, 
        # but Crossover might result in fewer if categories overlap heavily and we don't add extras)
        # The spec doesn't explicitly state min 2 for crossover, but it's a good invariant.
        # If we have < 2, we might need to duplicate or add generic.
        # For now, we trust the input genomes had valid structures.

        return child
